/* Progressive disclosure keeps reasoning readable on narrow screens. */
function deepLessonHTML(key){const d=topicDepth[key];if(!d)return '';return `<section class="deep-lesson"><div class="section-kicker">01 / ПОНИМАНИЕ</div><h3>Почему это работает</h3><p>${esc(d.why)}</p><div class="method-card"><span>↗</span><div><h4>Как подступиться к задаче</h4><p>${esc(d.method)}</p></div></div></section>`}
function conceptualHTML(key){const d=topicDepth[key];if(!d)return '';return `<section class="concept-check"><div class="section-kicker">ОБЪЯСНИ СВОИМИ СЛОВАМИ</div><h3>${esc(d.question)}</h3><p class="concept-prompt">Сначала сформулируй свою мысль, затем сравни с объяснением.</p><details><summary>Сравнить рассуждение</summary><p>${esc(d.answer)}</p></details></section>`}
function taskApproach(t){const d=topicDepth[`${t.grade}-${t.topic}`];return `<details class="approach-guide"><summary>Нужна идея для начала?</summary><p>${esc(t.review?.plan||d.method)}</p></details>`}
function solutionMarkup(t){const d=topicDepth[`${t.grade}-${t.topic}`];return `<p class="solution-note">Открывай шаги последовательно и объясняй переходы. Черновик автоматически не оценивается.</p><div class="solution-plan"><b>Идея решения</b><p>${esc(t.review?.plan||d.method)}</p></div><ol class="numbered-steps guided-steps">${t.steps.map((s,i)=>`<li data-solution-step="${i}" ${i?'hidden':''}><p>${s}</p>${t.review?.reasons?.[i]?`<div class="step-reason"><b>Почему</b> ${esc(t.review.reasons[i])}</div>`:''}</li>`).join('')}</ol><div class="solution-controls" ${t.steps.length<=1?'hidden':''}><button class="primary" id="revealNextStep">Следующий шаг →</button><button id="revealAllSteps">Показать все</button></div><p id="solutionStepStatus" class="solution-step-status" role="status">Шаг 1 из ${t.steps.length}</p><section id="solutionValidation" class="solution-validation" ${t.steps.length>1?'hidden':''}><b>Проверка и вывод</b><p>${esc(t.review?.verify||d.why)}</p><div class="solution-trap"><b>Частая ошибка</b><p>${esc(t.review?.trap||lessons[`${t.grade}-${t.topic}`].mistake)}</p></div></section>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!['revealNextStep','revealAllSteps'].includes(b.id))return;const steps=[...document.querySelectorAll('#solutionDetails [data-solution-step]')];if(b.id==='revealAllSteps')steps.forEach(s=>s.hidden=false);else{const next=steps.find(s=>s.hidden);if(next){next.hidden=false;if(motionAllowed())next.animate?.([{opacity:0,transform:'translateY(6px)'},{opacity:1,transform:'translateY(0)'}],{duration:220,easing:'ease-out'})}}const count=steps.filter(s=>!s.hidden).length;document.querySelector('#solutionStepStatus').textContent=`Шаг ${count} из ${steps.length}`;const done=count===steps.length;document.querySelector('.solution-controls').hidden=done;document.querySelector('#solutionValidation').hidden=!done});
// Normalize the numeric answer into the task's own unit before comparing.
Object.assign(physicsUnitOptions,{'км/ч':[['км/ч',1],['м/с',3.6]],'см³':[['см³',1],['л',1000],['м³',1e6]]});
